function parsePalmares(html) {
  if (typeof document === 'undefined') return [];

  const parts = html.split(/<img[^>]+>/);

  return parts.slice(1).map(part => {
    const div = document.createElement('div');
    div.innerHTML = part;

    const text = (div.textContent || '').replace(/\s+/g, ' ').trim();
    const colonIdx = text.indexOf(':');
    if (colonIdx === -1) return null;

    const competition = text.slice(0, colonIdx).trim();

    const links = [...div.querySelectorAll('a')].map(a => {
      const href = a.getAttribute('href') || '';
      const id_s = href.match(/\/(\d+)\.html$/)?.[1] ?? null;
      return { year: a.textContent.trim(), id_s };
    });

    let afterColon = text.slice(colonIdx + 1).trim();
    links.forEach(l => { afterColon = afterColon.replace(l.year, ''); });
    const plainYears = links.length === 0
      ? afterColon.split(/[,\s]+/).map(s => s.trim()).filter(Boolean)
      : [];

    const note = links.length === 0
      ? ''
      : afterColon.replace(/^[\s,]+|[\s,]+$/g, '').trim();

    return { competition, links, plainYears, note };
  }).filter(Boolean).filter(e => e.competition.length > 0);
}

